/* From Uiverse.io by vinodjangid07 - Tags: purple, button, click effect, shop now */
.__UIV_SCOPE__ .button {
  width: 180px;
  height: 40px;
  background-image: linear-gradient(rgb(214, 202, 254), rgb(158, 129, 254));
  border: none;
  border-radius: 50px;
  color: rgb(255, 255, 255);
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  cursor: pointer;
  box-shadow: 1px 3px 0px rgb(139, 113, 255);
  transition-duration: .3s;
}

.__UIV_SCOPE__ .cartIcon {
  width: 14px;
  height: fit-content;
}

.__UIV_SCOPE__ .cartIcon path {
  fill: white;
}

.__UIV_SCOPE__ .button:active {
  transform: translate(2px ,0px);
  box-shadow: 0px 1px 0px rgb(139, 113, 255);
  padding-bottom: 1px;
}
